<?php

namespace Database\Seeders;

use App\Models\Municipality;
use App\Models\Prospect;
use Illuminate\Database\Seeder;

class ProspectSeeder extends Seeder
{
    public function run(): void
    {
        $municipalities = [];

        foreach ($this->prospects() as $data) {
            $municipalityId = null;
            if (! empty($data['municipality'])) {
                $munName = $data['municipality'];
                if (! isset($municipalities[$munName])) {
                    $mun = Municipality::firstOrCreate(
                        ['name' => $munName],
                        ['department' => 'Olancho', 'country' => 'Honduras']
                    );
                    $municipalities[$munName] = $mun->id;
                }
                $municipalityId = $municipalities[$munName];
            }

            Prospect::create([
                'business_name' => $data['business_name'],
                'category' => $data['category'] ?? null,
                'municipality_id' => $municipalityId,
                'phone' => $data['phone'] ?? null,
                'address' => $data['address'] ?? null,
                'contact_name' => $data['contact'] ?? null,
                'origin' => $data['origin'] ?? null,
                'data_source' => $data['data_source'] ?? null,
                'nearby_screen' => $data['nearby_screen'] ?? null,
                'notes' => $data['notes'] ?? null,
                'status' => 'por_visitar',
            ]);
        }
    }

